import{_ as s,o as i,c as e,a2 as n}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Day 9: Build Logs, Debugging & Makefiles","description":"","frontmatter":{},"headers":[],"relativePath":"day9-build-logs-debugging-makefiles.md","filePath":"day9-build-logs-debugging-makefiles.md"}'),t={name:"day9-build-logs-debugging-makefiles.md"};function l(o,a,p,h,r,d){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="day-9-build-logs-debugging-makefiles" tabindex="-1">Day 9: Build Logs, Debugging &amp; Makefiles <a class="header-anchor" href="#day-9-build-logs-debugging-makefiles" aria-label="Permalink to &quot;Day 9: Build Logs, Debugging &amp; Makefiles&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Locate and interpret BitBake task execution logs (<code>log.do_*</code>)</li><li>Use Python-based messaging functions (<code>bbnote</code>, <code>bbwarn</code>, <code>bbfatal</code>) inside recipes</li><li>Understand how <code>oe_runmake</code> acts as a wrapper around the standard <code>make</code> command</li><li>Troubleshoot common <code>do_compile</code> failures related to Makefiles</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day8-writing-recipes-and-c-apps.html">Day 8: Writing Recipes &amp; C Applications</a></li></ul></div><hr><h2 id="_1-finding-and-reading-build-logs" tabindex="-1">1. Finding and Reading Build Logs <a class="header-anchor" href="#_1-finding-and-reading-build-logs" aria-label="Permalink to &quot;1. Finding and Reading Build Logs&quot;">​</a></h2><p>When a recipe fails to compile (e.g., a syntax error in your C code), BitBake will halt the entire build process and print a red error message to the console. However, the console output is often truncated. To find the <em>actual</em> compiler error (like <code>error: expected &#39;;&#39; before &#39;}&#39;</code>), you must look at the task logs.</p><p>Every task executed by BitBake generates a detailed log file inside the recipe&#39;s temporary <code>temp/</code> directory.</p><h3 id="locating-the-logs" tabindex="-1">Locating the Logs <a class="header-anchor" href="#locating-the-logs" aria-label="Permalink to &quot;Locating the Logs&quot;">​</a></h3><p>The path format is: <code>build/tmp/work/&lt;architecture&gt;/&lt;recipe-name&gt;/&lt;version&gt;/temp/</code></p><p>For example, if our <code>helloworld</code> recipe from Day 8 failed during compilation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tmp/work/cortexa8hf-neon-poky-linux-gnueabi/helloworld/1.0-r0/temp/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View the compilation log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log.do_compile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Other useful logs:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># log.do_fetch</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># log.do_configure</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># log.do_install</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">PRO TIP</p><p>When BitBake fails, it usually prints the exact absolute path to the log file in the console output. Always copy that path and <code>cat</code> it to see the underlying compiler error!</p></div><hr><h2 id="_2-emitting-custom-messages-bbnote-bbwarn" tabindex="-1">2. Emitting Custom Messages (<code>bbnote</code>, <code>bbwarn</code>) <a class="header-anchor" href="#_2-emitting-custom-messages-bbnote-bbwarn" aria-label="Permalink to &quot;2. Emitting Custom Messages (\`bbnote\`, \`bbwarn\`)&quot;">​</a></h2><p>Sometimes when writing complex recipes, you want to print messages to the console to verify variables or warn the user. Because recipes execute within BitBake&#39;s Python environment, you cannot just use <code>echo</code>. You must use BitBake&#39;s logging utilities.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # This prints a standard informational message to the log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    bbnote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Starting compilation with CC=\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # This prints a yellow warning to the main BitBake console</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    bbwarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Experimental feature enabled!&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # This prints a red error and HALTS the entire build immediately</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Makefile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        bbfatal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Makefile is missing! Cannot proceed.&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    fi</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    \${CC} \${CFLAGS} </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main.c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_3-working-with-makefiles-and-oe-runmake" tabindex="-1">3. Working with Makefiles and <code>oe_runmake</code> <a class="header-anchor" href="#_3-working-with-makefiles-and-oe-runmake" aria-label="Permalink to &quot;3. Working with Makefiles and \`oe_runmake\`&quot;">​</a></h2><p>In Day 8, we compiled a single C file by calling <code>\${CC}</code> directly. However, 99% of open-source projects use build systems like <code>Make</code>.</p><p>When a project has a <code>Makefile</code>, you shouldn&#39;t call <code>make</code> directly in your recipe. Instead, you use Yocto&#39;s wrapper function: <strong><code>oe_runmake</code></strong>.</p><h3 id="why-oe-runmake-instead-of-make" tabindex="-1">Why <code>oe_runmake</code> instead of <code>make</code>? <a class="header-anchor" href="#why-oe-runmake-instead-of-make" aria-label="Permalink to &quot;Why \`oe_runmake\` instead of \`make\`?&quot;">​</a></h3><p>If you just run <code>make</code>, the host&#39;s native GCC compiler might be invoked, producing an x86 binary instead of an ARM binary. <code>oe_runmake</code> automatically injects the correct cross-compilation environment variables (like <code>CC</code>, <code>LD</code>, <code>CFLAGS</code>, and parallel execution flags <code>-j8</code>) into the Make process.</p><h3 id="example-compiling-a-make-project" tabindex="-1">Example: Compiling a Make Project <a class="header-anchor" href="#example-compiling-a-make-project" aria-label="Permalink to &quot;Example: Compiling a Make Project&quot;">​</a></h3><p>Assume you fetch a tarball that extracts a source tree containing a <code>Makefile</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;An application built with Make&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LICENSE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MIT&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LIC_FILES_CHKSUM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://example.com/myapp-1.0.tar.gz&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># S defaults to \${WORKDIR}/\${BP}, which evaluates to \${WORKDIR}/myapp-1.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># which is exactly where the tarball extracts to!</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # This executes \`make -j8 CC=arm-linux-... CFLAGS=...\`</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    oe_runmake</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # If the Makefile supports standard DESTDIR installation:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    oe_runmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DESTDIR=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\${D} </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PREFIX=/usr</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="handling-bad-makefiles-extra-oemake" tabindex="-1">Handling Bad Makefiles (<code>EXTRA_OEMAKE</code>) <a class="header-anchor" href="#handling-bad-makefiles-extra-oemake" aria-label="Permalink to &quot;Handling Bad Makefiles (\`EXTRA_OEMAKE\`)&quot;">​</a></h3><p>Sometimes, poorly written Makefiles hardcode the compiler (<code>CC = gcc</code>). To force the Makefile to use Yocto&#39;s cross-compiler, you can pass arguments via the <code>EXTRA_OEMAKE</code> variable.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Force the Makefile to use our compiler and linker flags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXTRA_OEMAKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&#39;CC=\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39; &#39;CFLAGS=\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CFLAGS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    oe_runmake</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 9.1: Break the Build and Read the Log</p><ol><li>Open <code>helloworld.c</code> (from Day 8) and intentionally remove a semicolon <code>;</code>.</li><li>Rebuild the recipe: <code>bitbake -c clean helloworld &amp;&amp; bitbake helloworld</code>.</li><li>BitBake will fail. Find the path to <code>log.do_compile</code> in the red error text.</li><li><code>cat</code> the log file and locate the exact GCC error message complaining about the missing semicolon.</li><li>Fix the code and rebuild.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 9.2: Injecting Warnings</p><ol><li>Open your <code>helloworld_1.0.bb</code> recipe.</li><li>Inside the <code>do_compile</code> function, add: <code>bbwarn &quot;This is a custom warning from my recipe!&quot;</code></li><li>Rebuild the recipe.</li><li>Observe the yellow warning text appearing in the main BitBake terminal output during the build process.</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>BitBake Logging</td><td><a href="https://docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-metadata.html#logging" target="_blank" rel="noreferrer">docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-metadata.html#logging</a></td></tr><tr><td>oe_runmake documentation</td><td><a href="https://docs.yoctoproject.org/ref-manual/classes.html#make" target="_blank" rel="noreferrer">docs.yoctoproject.org/ref-manual/classes.html#make</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day8-writing-recipes-and-c-apps">← Day 8: Writing Recipes &amp; C Apps</a><a href="/day10-git-repositories-and-source-patching">Day 10: Git Repos &amp; Patching →</a></div>`,37)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
